using Confectory.Core;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace Confectory.Tests;

public sealed class PropertyBlueprintTests : TestCase
{
    const string Model="Confectory.ObjectModel", Owner="Api::Monster";
    static JsonObject Sig(string result, params Parameter[] args)=>FeatureBlueprint.SignatureDocument(new(args.ToList(),result));
    static JsonObject Bind(string key,string name)=>new(){[key]=name};
    static JsonObject Edge(string from,string to)=>new(){["from"]=from,["port"]="next",["to"]=to};
    static string Alias(string function)=>FeatureBlueprint.ImportAlias(Model+"::"+function);
    JsonObject Descriptor(string owner=Owner)
    {
        f.ExtraRegistry[Model]=Path.Combine(Fixture.Repo,"packs/object-model/pack.cpack");
        f.Packs["App"].Dependencies[Model]="0.1.0";f.Packs["Provider"].Dependencies[Model]="0.1.0";
        f.Add("Api","schema","Vitals","schema Api::Vitals {field health single general int;field reads single general int;field samples multiple general int;field peer single reference Api::Vitals;}");
        f.Add("Api","object","Monster","object Api::Monster {use schema Api::Vitals;data health = 999;}");
        f.Add("Api","object","Derived","object Api::Derived extends Api::Monster {}");
        f.Add("Api","object","Other","object Api::Other {use schema Api::Vitals;}");f.Sync();return RuntimeObjectContracts.Describe(f.Registry(),owner);
    }
    static JsonObject Field(JsonObject descriptor,string name)=>descriptor["fields"]!.AsArray().Single(f=>f!["name"]!.ToString()==name)!.AsObject();
    static JsonObject Code(string id,JsonObject sig,JsonObject args,params string[] imports)=>new(){["id"]=id,["kind"]="code",["control"]="next",["intent"]="Execute "+id,["signature"]=sig,["arguments"]=args,["implementation"]=id+".node.json",["imports"]=new JsonArray(imports.Select(x=>(JsonNode)JsonValue.Create(Model+"::"+x)!).ToArray())};
    static JsonObject Property(string id,JsonObject descriptor,string field,JsonObject target)=>new(){["id"]=id,["kind"]="property",["control"]="next",["intent"]="Read "+field+" at this node",["propertyOwner"]=descriptor["id"]!.DeepClone(),["field"]=field,["fieldContractHash"]=Field(descriptor,field)["hash"]!.DeepClone(),["signature"]=Sig(Field(descriptor,field)["clrType"]!.ToString(),new Parameter("object","target")),["arguments"]=new JsonObject{["target"]=target}};
    static JsonObject Graph(string feature)=>new(){["schema"]=1,["profile"]=FeatureBlueprint.PropertyProfile,["feature"]="Api::Value",["contractHash"]=FeatureBlueprint.ContractHash(new Parser(feature,"<property>").ParseElement()),["entry"]="read",["nodes"]=new JsonArray(),["edges"]=new JsonArray(),["exits"]=new JsonObject()};
    static JsonObject Contracts()=>new(new[]{"Read","Set","Write","Create","Access"}.Select(name=>new KeyValuePair<string,JsonNode?>(Model+"::"+name,JsonValue.Create(File.ReadAllText(Path.Combine(Fixture.Repo,"packs/object-model",name+".celem"))))));
    static JsonObject Query(JsonObject graph,string feature,JsonObject descriptor,string operation="featureBlueprintDescribe",JsonObject? records=null)=>FeatureBlueprint.Execute(new(){["operation"]=operation,["featureSource"]=feature,["graph"]=graph.DeepClone(),["propertyContracts"]=new JsonObject{[descriptor["id"]!.ToString()]=descriptor.DeepClone()},["featureContracts"]=Contracts(),["implementations"]=records?.DeepClone(),["implementationContext"]=new JsonObject{["implementation"]="Provider::ValueBody"},["bodyTarget"]="common"});
    void Write(JsonObject graph,string feature,JsonObject descriptor,Dictionary<string,string> bodies)
    {
        var defs=Query(graph,feature,descriptor,"featureBlueprintNodes");Equal("node-definitions",Text(defs,"state"));
        foreach(var pair in bodies){var definition=defs["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()==pair.Key)!;f.Body("Provider",pair.Key+".node.json",new JsonObject{["schema"]=1,["node"]=pair.Key,["definitionHash"]=definition["definitionHash"]!.DeepClone(),["source"]=pair.Value}.ToJsonString());}
        var sig=new Parser(feature,"<property>").ParseElement().Signature!;f.Add("Api","function","Value",feature);
        string Import(string name)=>"import "+Model+"::"+name+" as "+Alias(name)+" "+new Parser(Contracts()[Model+"::"+name]!.ToString(),"<model>").ParseElement().Signature!.Format(false)+";";
        f.Add("Provider","implementation","ValueBody","implementation Provider::ValueBody for Api::Value "+sig.Format()+" {"+Import("Read")+Import("Set")+Import("Write")+"blueprint common \"property.graph.json\";}");
        f.Add("App","implementation","MainBody","implementation App::MainBody for App::Main () -> int {import Api::Value as Value "+sig.Format(false)+";import "+Model+"::Create as Create (string,string[],object[]) -> object;import "+Model+"::Read as Read (object,string,string,string) -> object;import "+Model+"::Set as Set (object,string,string,string,object) -> void;import "+Model+"::Write as Write (object,string,object) -> void;import "+Model+"::Access as Access (object,string,string,string,object,bool) -> object;body common \"main.csbody\";}");
        f.Body("Provider","property.graph.json",graph.ToJsonString());f.Sync();
    }
    static string Quote(string value)=>JsonSerializer.Serialize(value);
    static JsonObject PropertySet(string id,JsonObject descriptor,string field,JsonObject target,JsonObject value)
    {
        var node=Property(id,descriptor,field,target);node["kind"]="property-set";node["intent"]="Set actual "+field;
        node["signature"]=Sig("void",new Parameter("object","target"),new Parameter(Field(descriptor,field)["clrType"]!.ToString(),"value"));node["arguments"]!["value"]=value;return node;
    }
    public void test_structural_property_set_executes_between_reads_on_actual_independent_instances()
    {
        var descriptor=Descriptor();const string feature="function Api::Value (object target,int replacement) -> int {}";var graph=Graph(feature);graph["profile"]=FeatureBlueprint.PropertySetProfile;
        graph["entry"]="before";graph["nodes"]=new JsonArray(Property("before",descriptor,"health",Bind("input","target")),PropertySet("set",descriptor,"health",Bind("input","target"),Bind("input","replacement")),Property("read",descriptor,"health",Bind("input","target")),Code("consume",Sig("int",new Parameter("int","before"),new Parameter("int","after")),new(){["before"]=Bind("node","before"),["after"]=Bind("node","read")}));
        graph["edges"]=new JsonArray(Edge("before","set"),Edge("set","read"),Edge("read","consume"),Edge("consume","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","consume")};
        var described=Query(graph,feature,descriptor);Equal("needs-implementation",Text(described,"state"));Equal(FeatureBlueprint.PropertySetGenerator,Text(described,"generator"));Equal("property-write",Text(described["nodes"]!.AsArray().Single(n=>n!["id"]!.ToString()=="set")!,"status"));
        Write(graph,feature,descriptor,new(){["consume"]="return before*100+after;"});string health=Quote(Field(descriptor,"health")["id"]!.ToString());var derived=RuntimeObjectContracts.Describe(f.Registry(),"Api::Derived");
        f.Body("App","main.csbody","object a=calls.Create.Invoke("+Quote(descriptor.ToJsonString())+",new[]{"+health+"},new object[]{10});object b=calls.Create.Invoke("+Quote(derived.ToJsonString())+",new[]{"+health+"},new object[]{40});Console.WriteLine(calls.Value.Invoke(a,20));Console.WriteLine(calls.Value.Invoke(a,30));Console.WriteLine(calls.Value.Invoke(b,50));Console.WriteLine(calls.Access.Invoke(a,\"\","+health+",\"\",null!,false));Console.WriteLine(calls.Access.Invoke(b,\"\","+health+",\"\",null!,false));return 0;");Output(Build(),"1020\n2030\n4050\n30\n50");
    }
    public void test_structural_set_preserves_general_array_and_single_multiple_reference_identity()
    {
        _=Descriptor();f.Add("Api","schema","Vitals","schema Api::Vitals {field health single general int;field samples multiple general int;field peer single reference Api::Vitals;field peers multiple reference Api::Vitals;}");f.Sync();var descriptor=RuntimeObjectContracts.Describe(f.Registry(),Owner);
        const string feature="function Api::Value (object target,int[] samples,object peer,object[] peers) -> int[] {}";var graph=Graph(feature);graph["profile"]=FeatureBlueprint.PropertySetProfile;graph["entry"]="samples";
        graph["nodes"]=new JsonArray(PropertySet("samples",descriptor,"samples",Bind("input","target"),Bind("input","samples")),PropertySet("peer",descriptor,"peer",Bind("input","target"),Bind("input","peer")),PropertySet("peers",descriptor,"peers",Bind("input","target"),Bind("input","peers")),Property("read",descriptor,"samples",Bind("input","target")));graph["edges"]=new JsonArray(Edge("samples","peer"),Edge("peer","peers"),Edge("peers","read"),Edge("read","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","read")};Write(graph,feature,descriptor,new());
        string H(string name)=>Quote(Field(descriptor,name)["id"]!.ToString());string Read(string field)=>"calls.Access.Invoke(a,\"\","+H(field)+",\"\",null!,false)";
        f.Body("App","main.csbody","string contract="+Quote(descriptor.ToJsonString())+";object a=calls.Create.Invoke(contract,Array.Empty<string>(),Array.Empty<object>());object b=calls.Create.Invoke(contract,new[]{"+H("health")+"},new object[]{7});object c=calls.Create.Invoke(contract,new[]{"+H("health")+"},new object[]{8});int[] values={2,3};object[] peers={b,c};var retained=calls.Value.Invoke(a,values,b,peers);Console.WriteLine(ReferenceEquals(retained,values));Console.WriteLine(ReferenceEquals("+Read("samples")+",values));Console.WriteLine(ReferenceEquals("+Read("peer")+",b));Console.WriteLine(ReferenceEquals("+Read("peers")+",peers));values[0]=9;peers[0]=c;Console.WriteLine(((int[])"+Read("samples")+")[0]);Console.WriteLine(ReferenceEquals(((object[])"+Read("peers")+")[0],c));return 0;");Output(Build(),"True\nTrue\nTrue\nTrue\n9\nTrue");
    }
    public void test_checked_set_refuses_wrong_owner_value_cardinality_hash_and_unsupported_without_mutation()
    {
        _=Descriptor();const string feature="function Api::Value (object target,int value) -> int {}";f.Add("Api","function","Value",feature);f.Add("Api","schema","Small","schema Api::Small {field n single general int;}");f.Add("Api","schema","Vitals","schema Api::Vitals {field health single general int;field samples multiple general int;field peer single reference Api::Vitals;field peers multiple reference Api::Vitals;field compound single compound Api::Small;field callback single function Api::Value;}");f.Add("Api","object","NoSchema","object Api::NoSchema {}");f.Sync();var descriptor=RuntimeObjectContracts.Describe(f.Registry(),Owner);var other=RuntimeObjectContracts.Describe(f.Registry(),"Api::Other");var noSchema=RuntimeObjectContracts.Describe(f.Registry(),"Api::NoSchema");
        var graph=Graph(feature);graph["profile"]=FeatureBlueprint.PropertySetProfile;graph["entry"]="set";graph["nodes"]=new JsonArray(PropertySet("set",descriptor,"health",Bind("input","target"),Bind("input","value")),Property("read",descriptor,"health",Bind("input","target")));graph["edges"]=new JsonArray(Edge("set","read"),Edge("read","exit:done"));graph["exits"]=new JsonObject{["done"]=Bind("node","read")};Write(graph,feature,descriptor,new());
        string QField(string name)=>Quote(Field(descriptor,name)["id"]!.ToString());string Hash(string name)=>Quote(Field(descriptor,name)["hash"]!.ToString());string Set(string field,string value,string owner="\"Api::Monster\"",string? hash=null)=>"calls.Set.Invoke(a,"+owner+","+QField(field)+","+(hash??Hash(field))+","+value+")";
        var checks=new[]{"calls.Value.Invoke(null!,9)","calls.Value.Invoke(new object(),9)","calls.Value.Invoke(other,9)",Set("health","9L"),Set("health","null!"),Set("samples","new long[]{1}"),Set("samples","1"),Set("peer","new object()"),Set("peer","foreign"),Set("peers","new object[]{foreign}"),Set("peers","other"),Set("health","9","\"\""),Set("health","9",hash:"\"\""),Set("health","9",hash:Quote(new string('0',64))),Set("health","9","\"Api::Other\""),Set("compound","other"),Set("callback","other")};
        f.Body("App","main.csbody","""
        void Refused(Action action){try{action();}catch(ArgumentException){Console.WriteLine("refused");return;}catch(InvalidOperationException){Console.WriteLine("refused");return;}catch(NotSupportedException){Console.WriteLine("refused");return;}throw new Exception("Set accepted an invalid contract/value");}
        """+"object a=calls.Create.Invoke("+Quote(descriptor.ToJsonString())+",new[]{"+QField("health")+"},new object[]{17});object other=calls.Create.Invoke("+Quote(other.ToJsonString())+",Array.Empty<string>(),Array.Empty<object>());object foreign=calls.Create.Invoke("+Quote(noSchema.ToJsonString())+",Array.Empty<string>(),Array.Empty<object>());"+string.Join("",checks.Select(c=>"Refused(()=>"+c+");"))+"Console.WriteLine(calls.Read.Invoke(a,\"Api::Monster\","+QField("health")+","+Hash("health")+"));return 0;");Output(Build(),string.Join("\n",Enumerable.Repeat("refused",checks.Length))+"\n17");
    }
    public void test_set_profile_is_explicit_and_stale_schema_value_ref_and_unsupported_are_rejected()
    {
        var descriptor=Descriptor();const string feature="function Api::Value (object target,int value) -> void {}";var graph=Graph(feature);graph["profile"]=FeatureBlueprint.PropertySetProfile;graph["entry"]="set";graph["nodes"]=new JsonArray(PropertySet("set",descriptor,"health",Bind("input","target"),Bind("input","value")));graph["edges"]=new JsonArray();
        Equal("source-ready",Text(Query(graph,feature,descriptor),"state"));foreach(string profile in new[]{FeatureBlueprint.PropertyProfile,FeatureBlueprint.MethodsProfile,FeatureBlueprint.SwitchProfile}){var old=graph.DeepClone().AsObject();old["profile"]=profile;Equal("GRAPH_NODE_KIND",Text(Query(old,feature,descriptor)["diagnostics"]![0]!,"code"));}
        var stale=descriptor.DeepClone().AsObject();Field(stale,"health")["hash"]=new string('0',64);Equal("PROPERTY_FIELD_STALE",Text(Query(graph,feature,stale)["diagnostics"]![0]!,"code"));var defs=Query(graph,feature,stale,"featureBlueprintNodes");Equal("PROPERTY_FIELD_STALE",Text(defs["nodes"]![0]!["definition"]!,"propertyError"));
        var unsupported=descriptor.DeepClone().AsObject();Field(unsupported,"health")["supported"]=false;Equal("PROPERTY_FIELD_UNSUPPORTED",Text(Query(graph,feature,unsupported)["diagnostics"]![0]!,"code"));var wrong=graph.DeepClone().AsObject();wrong["nodes"]![0]!["signature"]!["args"]![1]!["mode"]="ref";Equal("PROPERTY_SIGNATURE",Text(Query(wrong,feature,descriptor)["diagnostics"]![0]!,"code"));wrong=graph.DeepClone().AsObject();wrong["nodes"]![0]!["arguments"]!["value"]=new JsonObject{["constant"]="wrong"};Equal("GRAPH_CONSTANT_TYPE",Text(Query(wrong,feature,descriptor)["diagnostics"]![0]!,"code"));
    }
    public void test_set_all_general_primitive_and_array_clr_contracts_without_conversion_or_copy()
    {
        _=Descriptor();string[] types={"bool","int","long","float","double","string"},values={"true","12","34L","1.5F","2.5D","\"actual\""};
        var parameters=new List<Parameter>{new("object","target")};var schema=new System.Text.StringBuilder("schema Api::Vitals {");
        for(int i=0;i<types.Length;i++){schema.Append("field atom"+i+" single general "+types[i]+";field array"+i+" multiple general "+types[i]+";");parameters.Add(new(types[i],"atom"+i));parameters.Add(new(types[i]+"[]","array"+i));}schema.Append('}');f.Add("Api","schema","Vitals",schema.ToString());f.Sync();var descriptor=RuntimeObjectContracts.Describe(f.Registry(),Owner);
        string feature="function Api::Value "+new FunctionSignature(parameters,"void").Format()+" {}";var graph=Graph(feature);graph["profile"]=FeatureBlueprint.PropertySetProfile;var nodes=graph["nodes"]!.AsArray();var edges=graph["edges"]!.AsArray();string? prior=null;
        foreach(var parameter in parameters.Skip(1)){nodes.Add(PropertySet(parameter.Name,descriptor,parameter.Name,Bind("input","target"),Bind("input",parameter.Name)));if(prior is not null)edges.Add(Edge(prior,parameter.Name));prior=parameter.Name;}graph["entry"]="atom0";Write(graph,feature,descriptor,new());
        var body=new System.Text.StringBuilder("object target=calls.Create.Invoke("+Quote(descriptor.ToJsonString())+",Array.Empty<string>(),Array.Empty<object>());");var args=new List<string>{"target"};for(int i=0;i<types.Length;i++){body.Append(types[i]+"[] array"+i+"={"+values[i]+"};");args.Add(values[i]);args.Add("array"+i);}body.Append("calls.Value.Invoke("+string.Join(",",args)+");");
        for(int i=0;i<types.Length;i++){string Read(string field)=>"calls.Read.Invoke(target,\"Api::Monster\","+Quote(Field(descriptor,field)["id"]!.ToString())+","+Quote(Field(descriptor,field)["hash"]!.ToString())+")";body.Append("Console.WriteLine("+Read("atom"+i)+".GetType()==typeof("+types[i]+")&&Equals("+Read("atom"+i)+","+values[i]+"));Console.WriteLine(ReferenceEquals("+Read("array"+i)+",array"+i+"));");}body.Append("return 0;");f.Body("App","main.csbody",body.ToString());Output(Build(),string.Join("\n",Enumerable.Repeat("True",12)));
    }
