        Write(graph,feature,descriptor,new(){["before"]=Alias("Write")+".Invoke(target,"+Quote(health)+",value);",["after"]=Alias("Write")+".Invoke(target,"+Quote(health)+",value);",["consume"]="return first*100+second;"});
